network_notes.test_script_code:
// Gọi tuần tự trong TIA Portal (SCL) với 2 Slave
IF NOT "DB_MB".bInitDone THEN
    "MB_COMM_LOAD_DB"(REQ := TRUE, PORT := "Local~CB_1241_(RS485)",
        BAUD := 9600, PARITY := 2, MB_DB := "MB_MASTER_DB");
    "DB_MB".bInitDone := "MB_COMM_LOAD_DB".DONE;
END_IF;

"MB_MASTER_DB"(
    REQ := "Clock_5Hz",
    MB_ADDR := 1,
    MODE := 1,              // 0: Read, 1: Write
    DATA_ADDR := 40002,     // Thanh ghi lệnh chạy 0x0001
    DATA_LEN := 2,
    DATA_PTR := "DB_MB".WriteBuf
);

